I(P(66),"예상 오답 — 쓸고 간 넓이를 원점(중심) 기준 부채꼴로 계산해 $t=\\theta$로 두고 속력을 상수로 본 경우",
 ["초점 기준 넓이 $S(\\theta)=\\frac{15}2\\theta-6\\sin\\theta$ (수선의 발 위치 두 경우가 한 식).",
  "$t=\\theta-\\frac45\\sin\\theta$, $s^2=\\frac{25(5+4\\cos\\theta)}{5-4\\cos\\theta}$ → $\\theta$로 치환하면 $5(5+4\\cos\\theta)$."],
 {'C1':("타원",r"초점 $(\pm4,0)$, 장축 $10$; $\mathrm A(5,0)$, $\mathrm B(0,3)$."),'C2':("운동",r"$\mathrm A$에서 $\mathrm B$까지 시계 반대 방향."),'C3':("넓이 법칙",r"초점에서 쓸고 간 넓이 $=\frac{15}2t$."),
  'C4':("속력",r"$s(t)$."),'C5':("적분",r"$\int_0^Ts^2dt=\frac a2\pi+b$."),'C7':("묻는 것",r"$a+b$."),'C8':("자연수",r"$a$, $b$ 자연수.")},
 [("케플러 제2법칙",[r"면적 속도 일정."]),("매개변수 적분",[r"$\int s^2dt=\int s^2\frac{dt}{d\theta}d\theta$."])],
 [("의도",['C3']),("타원",['C1']),("호 아래 넓이",['C3']),("적분",['C3']),("삼각형",['C3']),("$S(\\theta)$",['C3']),("$t$와 $\\theta$",['C3']),("속도",['C4']),("$s^2$",['C4']),("초점 거리",['C4']),("치환",['C5']),("답",['C7','C8'])],
 [("초점 기준",'C3',[r"중심이 아니라 $\mathrm F$에서 그은 선분."]),("한 식",'C3',[r"$\mathrm H$가 $\mathrm F$의 좌·우 어디든 $S=\frac{15}2\theta-6\sin\theta$."])],
 [("변형 · 초점 $(\\pm3,0)$",[r"두 점 $(3,0)$, $(-3,0)$을 초점으로 하고 장축의 길이가 $10$인 타원 위에서, 점 $\mathrm P$가 $t=0$에 $\mathrm A(5,0)$을 출발하여 시계 반대 방향으로 움직여 $t=T$에 $\mathrm B(0,4)$에 도착한다. $0<t\le T$에서 선분 $\mathrm{FA}$, 선분 $\mathrm{FP}$ ($\mathrm F(3,0)$)와 $\mathrm P$가 지나온 호로 둘러싸인 넓이가 $10t$일 때, 속력 $s(t)$에 대하여 $\int_0^T\{s(t)\}^2dt=\frac a2\pi+b$이다. $a+b$의 값을 구하시오. (단, $a$, $b$는 자연수)"],40,r"$t=\theta-\frac35\sin\theta$; $\int_0^{\pi/2}5(5+3\cos\theta)d\theta$.")],
 "초점 면적 속도 일정 → 시각과 이심 이각의 관계.")

I(P(67),"예상 오답 — 피적분함수가 진동하므로 $a_n$이 단조 증가한다고 보거나 홀수·짝수 번째의 엇갈림을 놓친 경우",
 ["봉우리 $c_k=\\int|\\sin x^2|$를 $x=\\sqrt{u^2+\\pi}$로 앞 구간에 옮기면 $c_{k+1}<c_k$.",
  "홀수 번째 감소, 짝수 번째 증가, 모든 짝수 번째 < 모든 홀수 번째."],
 {'C2':("수열",r"$a_n=\int_0^{\sqrt{n\pi}}\sin(x^2)dx$."),'C4':("묻는 것",r"$1\le m<n\le20$에서 $a_m<a_n$인 순서쌍의 수.")},
 [("치환으로 비교",[r"구간을 맞추고 인수 $\frac u{\sqrt{u^2+\pi}}<1$."]),("교대 수열",[r"감소하는 봉우리의 교대 합."])],
 [("의도",['C2']),("봉우리",['C2']),("치환",['C2']),("비교",['C2']),("결론",['C2']),("홀짝",['C2']),("엇갈림",['C2']),("순서",['C4']),("답",['C4'])],
 [("부정적분 없음",'C2',[r"값을 구하지 않고 대소만."]),("짝·홀",'C4',[r"$m$ 짝, $n$ 홀이면 항상 $a_m<a_n$."])],
 [("변형 · $n\\le10$",[r"(같은 수열에서) $1\le m<n\le10$인 두 자연수 $m$, $n$의 순서쌍 $(m,n)$ 중에서 $a_m<a_n$을 만족시키는 것의 개수를 구하시오."],20,r"짝·짝 ${}_5\mathrm C_2=10$ + 짝·홀 $4+3+2+1=10$.")],
 "구할 수 없는 적분의 대소 → 치환으로 봉우리 비교.")

I(P(68),"예상 오답 — 세 색이 모두 쓰인 조건을 무시하고 원형 색칠 공식을 그대로 써 짝수 길이의 두 색 교대 배치를 빼지 않은 경우",
 ["같은 색 쌍 $j$개의 위치를 정하면 원탁이 $7-j$칸의 '이웃이 다른' 원형 색칠로 줄어듦.",
  "원형 색칠 $e_m$에서 두 색 교대(짝수 $m$)를 빼면 세 색 모두 쓰는 경우."],
 {'C1':("원탁",r"$7$명."),'C2':("모자",r"세 색 중 하나."),'C3':("확률",r"각 $\frac13$, 독립."),'C4':("$X$",r"같은 색 이웃 쌍의 수."),'C5':("조건부",r"세 색 모두 있을 때 $X\ge3$일 확률 $\frac qp$."),'C6':("묻는 것",r"$p+q$."),'C7':("서로소",r"기약분수.")},
 [("원형 색칠",[r"$e_m=3\cdot2^{m-1}-e_{m-1}$, $e_m=2^m+2(-1)^m$."]),("묶기",[r"같은 색 이웃을 한 덩어리로."])],
 [("의도",['C4']),("$n(A)$",['C2','C3']),("묶기",['C4']),("원형 색칠",['C4']),("점화식",['C4']),("두 색 제외",['C5']),("분포",['C5']),("검산",['C5']),("확률",['C5']),("답",['C6','C7'])],
 [("두 색 교대",'C5',[r"짝수 칸이면 두 색만으로 이웃이 다를 수 있음."]),("$X=6$",'C4',[r"$7$쌍 중 $6$쌍이 같으면 나머지도 같음 — 불가."])],
 [("변형 · $6$명, $X\\ge2$",[r"$6$명의 학생이 원탁에 둘러앉아 (같은 방법으로) 세 색 중 하나의 모자를 쓴다. $6$명이 쓴 모자에 세 가지 색이 모두 있을 때, 같은 색인 이웃 쌍의 개수 $X$가 $2$ 이상일 확률이 $\frac qp$이다. $p+q$의 값을 구하시오. (단, $p$와 $q$는 서로소인 자연수이다.)"],14,r"$\frac59$.")],
 "같은 색 이웃 묶기 → 더 작은 원형 색칠.")

I(P(69),"예상 오답 — 수직이등분선들이 덮는 영역을 원 $K$ 바깥으로 보거나, 타원 경계 위의 점까지 포함해 센 경우",
 ["$\\mathrm X$를 지나는 $l_{\\mathrm Q}$의 수 = $\\mathrm X$ 중심, $\\mathrm A$를 지나는 원과 $K$의 교점 수.",
  "만날 조건은 $\\overline{\\mathrm{XO}}+\\overline{\\mathrm{XA}}\\ge10$ 하나 → 지나지 않는 점은 타원 내부."],
 {'C1':("원과 점",r"$K$: 반지름 $10$, $\mathrm A(6,0)$."),'C2':("직선",r"$\mathrm{AQ}$의 수직이등분선 $l_{\mathrm Q}$."),'C3':("묻는 것",r"어느 $l_{\mathrm Q}$도 지나지 않는 격자점의 수.")},
 [("수직이등분선",[r"$\overline{\mathrm{XQ}}=\overline{\mathrm{XA}}$."]),("두 원의 위치 관계",[r"$|r_1-r_2|\le d\le r_1+r_2$."])],
 [("의도",['C2']),("원으로",['C2']),("조건",['C1']),("남는 조건",['C1']),("등호",['C3']),("타원",['C3']),("세기",['C3']),("답",['C3'])],
 [("저절로 성립",'C1',[r"$\mathrm A$가 $K$ 안이라 다른 두 부등식은 자동."]),("경계",'C3',[r"등호면 접선 하나가 지남 — 제외."])],
 [("변형 · $\\mathrm A(8,0)$",[r"(같은 원 $K$에 대하여) 점 $\mathrm A(8,\,0)$과 $K$ 위의 점 $\mathrm Q$에 대하여 선분 $\mathrm{AQ}$의 수직이등분선을 $l_{\mathrm Q}$라 하자. $\mathrm Q$가 $K$ 위를 움직일 때 생기는 직선 $l_{\mathrm Q}$ 중 어느 것도 지나지 않는 점 중에서 $x$좌표와 $y$좌표가 모두 정수인 점의 개수를 구하시오."],41,r"타원 $\frac{(x-4)^2}{25}+\frac{y^2}9<1$.")],
 "접기로 만든 직선들의 포락선 = 타원.")

I(P(70),"예상 오답 — $g$가 극대점에서 평평해지기 시작하는 경우만 생각해 넓이 상한 $108$에 막히는 경우",
 ["$g$가 일정해지기 시작하는 극대점은 매끄럽고, 일정 구간이 끝나는 점만 꺾임 → 끝점이 $6$.",
  "극대점에서 시작하면 넓이 $\\le108<180$ → $f'(0)<0$, $f=x(x-6)(x-s)$."],
 {'C1':("함수",r"최고차 $1$인 삼차, $f(0)=0$."),'C2':("$g$",r"$[0,x]$에서 $f$의 최댓값."),'C4':("(가)",r"미분가능하지 않은 점은 $x=6$ 하나."),'C5':("(나)",r"$\int_0^6(g-f)=180$."),'C6':("묻는 것",r"$f(9)$.")},
 [("누적 최댓값",[r"$g\ge f$, 평평 구간과 일치 구간."]),("넓이 공식",[r"$\int_0^Lu^2(L-u)du=\frac{L^4}{12}$."])],
 [("의도",['C2']),("성질",['C2']),("꺾이는 점",['C4']),("(ⅰ)",['C4','C5']),("상한",['C5']),("(ⅱ)",['C1','C4']),("적분",['C5']),("$s$",['C5']),("답",['C6'])],
 [("시작점",'C4',[r"극대점에서 $f'=0$이라 매끄러움."]),("$x=0$",'C4',[r"$f'(0)<0$이면 처음부터 평평."])],
 [("변형 · 넓이 $144$",[r"최고차항의 계수가 $1$인 삼차함수 $f(x)$가 $f(0)=0$을 만족시키고, $x\ge0$에서 $[0,x]$에서의 $f(t)$의 최댓값을 $g(x)$라 하자. (가) $(0,\infty)$에서 $g$가 미분가능하지 않은 점은 $x=6$ 하나뿐이다. (나) $\int_0^6\{g(x)-f(x)\}dx=144$. $f(9)$의 값을 구하시오."],270,r"$108-36s=144$ → $s=-1$, $f=x(x-6)(x+1)$.")],
 "누적 최댓값 → 평평 구간의 끝만 꺾임.")
